CREATE TABLE `cid_catalog_releases` (
	`id` text PRIMARY KEY NOT NULL,
	`classification` text NOT NULL,
	`version` text NOT NULL,
	`source_url` text NOT NULL,
	`source_sha256` text NOT NULL,
	`active` integer DEFAULT true NOT NULL,
	`imported_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX `uq_cid_catalog_release` ON `cid_catalog_releases` (`classification`,`version`);--> statement-breakpoint
CREATE TABLE `cid_codes` (
	`id` text PRIMARY KEY NOT NULL,
	`release_id` text NOT NULL,
	`code` text NOT NULL,
	`code_search` text NOT NULL,
	`description` text NOT NULL,
	`search_description` text NOT NULL,
	`category` text NOT NULL,
	`version` text NOT NULL,
	`classification_type` text DEFAULT '' NOT NULL,
	`sex_restriction` text DEFAULT '' NOT NULL,
	`mortality_restriction` text DEFAULT '' NOT NULL,
	`reference_code` text DEFAULT '' NOT NULL,
	`excluded_codes` text DEFAULT '' NOT NULL,
	`active` integer DEFAULT true NOT NULL,
	FOREIGN KEY (`release_id`) REFERENCES `cid_catalog_releases`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `uq_cid_codes_release_code` ON `cid_codes` (`release_id`,`code`);--> statement-breakpoint
CREATE INDEX `idx_cid_codes_active_code` ON `cid_codes` (`active`,`code_search`);--> statement-breakpoint
CREATE INDEX `idx_cid_codes_search_description` ON `cid_codes` (`search_description`);--> statement-breakpoint
CREATE TABLE `encounter_diagnoses` (
	`id` text PRIMARY KEY NOT NULL,
	`encounter_id` text NOT NULL,
	`cid_id` text NOT NULL,
	`type` text DEFAULT 'hypothesis' NOT NULL,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	FOREIGN KEY (`encounter_id`) REFERENCES `encounters`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`cid_id`) REFERENCES `cid_codes`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `uq_encounter_diagnoses_encounter_cid` ON `encounter_diagnoses` (`encounter_id`,`cid_id`);--> statement-breakpoint
CREATE INDEX `idx_encounter_diagnoses_encounter` ON `encounter_diagnoses` (`encounter_id`);--> statement-breakpoint
ALTER TABLE `encounters` ADD `status` text DEFAULT 'active' NOT NULL;--> statement-breakpoint
ALTER TABLE `encounters` ADD `cancelled_at` text;--> statement-breakpoint
ALTER TABLE `encounters` ADD `cancelled_by_user_id` text REFERENCES users(id);--> statement-breakpoint
ALTER TABLE `encounters` ADD `cancellation_reason` text;--> statement-breakpoint
CREATE INDEX `idx_encounters_patient_status_occurred` ON `encounters` (`patient_id`,`status`,`occurred_at`);--> statement-breakpoint
CREATE VIRTUAL TABLE `cid_codes_fts` USING fts5(code, description, content='cid_codes', content_rowid='rowid', tokenize='unicode61 remove_diacritics 2');--> statement-breakpoint
CREATE TRIGGER `cid_codes_ai` AFTER INSERT ON `cid_codes` BEGIN INSERT INTO cid_codes_fts(rowid, code, description) VALUES (new.rowid, new.code, new.description); END;--> statement-breakpoint
CREATE TRIGGER `cid_codes_ad` AFTER DELETE ON `cid_codes` BEGIN INSERT INTO cid_codes_fts(cid_codes_fts, rowid, code, description) VALUES ('delete', old.rowid, old.code, old.description); END;--> statement-breakpoint
CREATE TRIGGER `cid_codes_au` AFTER UPDATE ON `cid_codes` BEGIN INSERT INTO cid_codes_fts(cid_codes_fts, rowid, code, description) VALUES ('delete', old.rowid, old.code, old.description); INSERT INTO cid_codes_fts(rowid, code, description) VALUES (new.rowid, new.code, new.description); END;


